import pandas as pd
import matplotlib.pyplot as plt
import base64
from io import BytesIO
import datetime

def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    plt.close(fig)
    return base64.b64encode(buf.getvalue()).decode()

def classify_orbit(row):
    try:
        ecc = float(row['ECCENTRICITY'])
    except:
        ecc = 0
    mm = float(row['MEAN_MOTION'])

    if ecc > 0.25:
        return 'HEO'
    elif mm > 11.25:
        return 'LEO'
    elif 0.9 <= mm <= 1.1:
        return 'GEO'
    else:
        return 'MEO'

def get_constellation(name):
    name = str(name).strip()
    if name.startswith('STARLINK'):
        return 'Starlink'
    elif name.startswith('ONEWEB'):
        return 'OneWeb'
    elif name.startswith('FLOCK'):
        return 'Planet Flock'
    elif name.startswith('SPACEBEE'):
        return 'Swarm SpaceBEE'
    elif name.startswith('LEMUR'):
        return 'Spire LEMUR'
    elif 'GPS' in name or 'NAVSTAR' in name:
        return 'GPS'
    elif 'GALILEO' in name or 'GSAT' in name:
        return 'Galileo'
    elif 'GLONASS' in name or 'COSMOS' in name: # Note COSMOS can be many things, let's keep it simple
        if 'GLONASS' in name:
            return 'GLONASS'
    elif name.startswith('IRIDIUM'):
        return 'Iridium'
    elif name.startswith('GLOBALSTAR'):
        return 'Globalstar'
    elif name.startswith('O3B'):
        return 'O3b'
    elif name.startswith('QIANFAN'):
        return 'Qianfan'
    elif name.startswith('YAOGAN'):
        return 'Yaogan'
    elif name.startswith('HUAXIAN'):
        return 'Huaxian'
    elif name.startswith('JILIN'):
        return 'Jilin'
    return 'Other'

def main():
    # 1. Load Data
    df = pd.read_csv('/app/benchmark/data.csv')

    # Clean data
    # ECCENTRICITY comes like ".002524" -> "0.002524"
    df['ECCENTRICITY'] = df['ECCENTRICITY'].astype(str).str.replace(r'^\.', '0.', regex=True).astype(float)
    df['Launch_Year'] = df['OBJECT_ID'].astype(str).str[:4].astype(int)

    # 2. Compute KPIs
    total_satellites = len(df)
    leo_share = (len(df[df['MEAN_MOTION'] > 14]) / total_satellites) * 100
    starlink_size = len(df[df['OBJECT_NAME'].str.startswith('STARLINK', na=False)])
    median_inclination = df['INCLINATION'].median()
    launched_since_2020 = len(df[df['Launch_Year'] >= 2020])

    df['Orbit_Regime'] = df.apply(classify_orbit, axis=1)
    df['Constellation'] = df['OBJECT_NAME'].apply(get_constellation)

    # 3. Visualizations

    # Chart 1: Orbit Regime
    fig1, ax1 = plt.subplots(figsize=(8, 5))
    regime_counts = df['Orbit_Regime'].value_counts()
    regime_counts.plot(kind='bar', color=['#4472C4', '#ED7D31', '#A5A5A5', '#FFC000'], ax=ax1)
    ax1.set_title('Distribution of Satellites by Orbital Regime', fontsize=14, fontweight='bold')
    ax1.set_ylabel('Number of Satellites')
    ax1.set_xticklabels(ax1.get_xticklabels(), rotation=0)
    for p in ax1.patches:
        ax1.annotate(str(p.get_height()), (p.get_x() + p.get_width() / 2., p.get_height()), ha='center', va='bottom')
    chart1_b64 = fig_to_base64(fig1)

    # Chart 2: Top Constellations
    fig2, ax2 = plt.subplots(figsize=(10, 6))
    top_const = df[df['Constellation'] != 'Other']['Constellation'].value_counts().head(10)
    top_const.sort_values().plot(kind='barh', color='#4472C4', ax=ax2)
    ax2.set_title('Top 10 Satellite Constellations by Active Count', fontsize=14, fontweight='bold')
    ax2.set_xlabel('Number of Satellites')
    for i, v in enumerate(top_const.sort_values()):
        ax2.text(v + 10, i - 0.1, str(v), color='black')
    chart2_b64 = fig_to_base64(fig2)

    # Chart 3: Launch Trends
    fig3, ax3 = plt.subplots(figsize=(12, 6))
    yearly_launches = df['Launch_Year'].value_counts().sort_index()
    yearly_launches = yearly_launches[yearly_launches.index >= 1990] # Focus on recent decades
    ax3.plot(yearly_launches.index, yearly_launches.values, marker='o', linestyle='-', color='#ED7D31', linewidth=2)
    ax3.set_title('Active Satellites by Launch Year (1990 - Present)', fontsize=14, fontweight='bold')
    ax3.set_xlabel('Launch Year')
    ax3.set_ylabel('Number of Active Satellites')
    ax3.grid(True, linestyle='--', alpha=0.7)
    chart3_b64 = fig_to_base64(fig3)

    # Chart 4: Inclination vs Mean Motion
    fig4, ax4 = plt.subplots(figsize=(10, 6))
    ax4.scatter(df['MEAN_MOTION'], df['INCLINATION'], alpha=0.1, color='#4472C4', s=10)
    ax4.set_title('Orbital Parameters: Inclination vs. Mean Motion', fontsize=14, fontweight='bold')
    ax4.set_xlabel('Mean Motion (revolutions/day)')
    ax4.set_ylabel('Inclination (degrees)')
    ax4.grid(True, linestyle='--', alpha=0.7)
    chart4_b64 = fig_to_base64(fig4)

